        async def _extract_companion_handoff_url() -> str:
            """Best-effort extraction of the mobile handoff URL from clipboard or DOM."""
            try:
                return await self.page.evaluate(
                    """
                    () => {
                      const candidates = [];
                      if (window.__ageVerifyClipboard) {
                        candidates.push(window.__ageVerifyClipboard);
                      }

                      const text = document.body ? document.body.innerText : '';
                      candidates.push(text);

                      for (const el of document.querySelectorAll('a, input, textarea')) {
                        const href = el.getAttribute && el.getAttribute('href');
                        const value = 'value' in el ? el.value : '';
                        const textContent = (el.innerText || el.textContent || '').trim();
                        if (href) candidates.push(href);
                        if (value) candidates.push(value);
                        if (textContent) candidates.push(textContent);
                      }

                      const patterns = [
                        /https?:\\/\\/[^\\s"'<>]*\\/handoff-age\\?handoffId=[A-Za-z0-9-]+[^\\s"'<>]*/i,
                        /https?:\\/\\/[^\\s"'<>]*\\/handoff\\?handoffId=[A-Za-z0-9-]+/i,
                        /https?:\\/\\/[^\\s"'<>]*\\/mobile-flow[^\\s"'<>]*/i,
                        /\\/handoff-age\\?handoffId=[A-Za-z0-9-]+[^\\s"'<>]*/i,
                        /\\/handoff\\?handoffId=[A-Za-z0-9-]+/i,
                        /\\/mobile-flow[^\\s"'<>]*/i,
                      ];

                      for (const raw of candidates) {
                        if (typeof raw !== 'string' || !raw.trim()) continue;
                        for (const pattern of patterns) {
                          const match = raw.match(pattern);
                          if (match) return match[0];
                        }
                      }

                      return '';
                    }
                    """
                )
            except Exception:
                return ""

        async def _create_companion_handoff_via_api(current_url: str) -> str:
            """Create an age-verification handoff directly from the backend API."""
            parsed = urlsplit(current_url)
            params = parse_qsl(parsed.query, keep_blank_values=True)
            session_id = next((value for key, value in params if key == "sessionId" and value), "")
            if not session_id:
                return ""

            api_url = f"https://api-age-verification.privateid.com/session/{session_id}/handoff"
            try:
                response = requests.post(
                    api_url,
                    json={"type": "QR_CODE"},
                    headers={"content-type": "application/json"},
                    timeout=20,
                )
            except Exception as e:
                log(f"companion API 创建 handoff 失败: {e}")
                return ""

            if response.status_code >= 400:
                log(
                    "companion API 创建 handoff 失败: "
                    f"status={response.status_code} body={response.text[:240]}"
                )
                return ""

            try:
                data = response.json()
            except Exception as e:
                log(f"companion API 响应 JSON 解析失败: {e}")
                return ""

            handoff_id = data.get("id")
            if not handoff_id:
                log(f"companion API 未返回 handoff id: {str(data)[:240]}")
                return ""

            handoff_params = [(key, value) for key, value in params if key != "sessionId"]
            handoff_params.append(("handoffId", handoff_id))
            handoff_query = urlencode(handoff_params)
            origin = f"{parsed.scheme}://{parsed.netloc}" if parsed.scheme and parsed.netloc else "https://age-verification.privateid.com"
            return f"{origin}/handoff-age?{handoff_query}" if handoff_query else f"{origin}/handoff-age"

        async def _activate_companion_link_flow(current_url: str, current_text: str) -> bool:
            """Switch companion page to link mode and navigate to the generated mobile link."""
            if "switch-device-age" not in current_url:
                return False
            text_lower = current_text.lower()
            if not any(phrase in text_lower for phrase in [
                "use your phone",          # English
                "sử dụng điện thoại",      # Vietnamese
                "使用您的手机",             # Chinese
                "ใช้โทรศัพท์",             # Thai
                "gunakan ponsel",          # Indonesian
            ]):
                return False

            direct_handoff_url = await _create_companion_handoff_via_api(current_url)
            if direct_handoff_url:
                log(f"通过 companion API 生成 handoff 链接: {direct_handoff_url}")
                await self.page.goto(direct_handoff_url, wait_until="domcontentloaded", timeout=30000)
                clicked_buttons.append("Companion handoff api")
                return True

            try:
                switched = await self.page.evaluate(
                    """
                    () => {
                      const clickLikeUser = (el) => {
                        if (!el) return false;
                        const events = ['pointerdown', 'mousedown', 'pointerup', 'mouseup', 'click'];
                        for (const type of events) {
                          el.dispatchEvent(new MouseEvent(type, { bubbles: true, cancelable: true, view: window }));
                        }
                        return true;
                      };

                      const buttons = Array.from(document.querySelectorAll('button, [role="button"], a'));
                      const linkTab = buttons.find((el) => {
                        const text = (el.innerText || el.textContent || '').trim().toLowerCase();
                        return text === 'link' || text === 'open link' || text === 'continue on this device';
                      });
                      if (!clickLikeUser(linkTab)) return { switched: false, copyClicked: false };

                      const copyButton = buttons.find((el) => {
                        const text = (el.innerText || el.textContent || '').trim().toLowerCase();
                        return text === 'copy link' || text === 'open link' || text === 'continue on this device';
                      });

                      if (copyButton) {
                        clickLikeUser(copyButton);
                      }

                      const activeTab = buttons.find((el) => (el.getAttribute('data-state') || '').toLowerCase() === 'active');
                      return {
                        switched: true,
                        copyClicked: !!copyButton,
                        activeTabText: activeTab ? (activeTab.innerText || activeTab.textContent || '').trim() : '',
                      };
                    }
                    """
                )
            except Exception as e:
                log(f"检测 companion Link 模式失败: {e}")
                return False

            if switched and switched.get("switched"):
                log(
                    "检测到 companion 页，已切换到 Link tab"
                    + (f" (active={switched.get('activeTabText', '')})" if switched.get("activeTabText") else "")
                )
                if switched.get("copyClicked"):
                    log("检测到 companion 页，已点击 Copy/Open Link 按钮")

                await asyncio.sleep(1.2)
                handoff_url = await _extract_companion_handoff_url()
                if handoff_url:
                    if handoff_url.startswith("/"):
                        handoff_url = f"{self.page.url.split('/switch-device-age')[0]}{handoff_url}"
                    log(f"检测到 handoff 链接，直接跳转: {handoff_url}")
                    await self.page.goto(handoff_url, wait_until="domcontentloaded", timeout=30000)
                    clicked_buttons.append("Companion handoff")
                    return True

                log("Link tab 已激活，但暂未提取到 handoff 链接")
                clicked_buttons.append("Link")
                return True

            return False

        async def _log_page_diagnostics(prefix: str):
            try:
                log(f"{prefix} 当前 URL: {self.page.url}")
            except Exception:
                pass

            for idx, frame in enumerate(self.page.frames):
                try:
                    frame_url = frame.url
                except Exception:
                    frame_url = "<unknown>"
                try:
                    frame_text = await frame.evaluate("document.body ? document.body.innerText : ''")
                    frame_text = " ".join(frame_text.split())[:300]
                except Exception:
                    frame_text = ""
                try:
                    candidates = await frame.evaluate(
                        """
                        () => Array.from(document.querySelectorAll('button, [role="button"], input[type="button"], input[type="submit"], a'))
                          .map((el) => ({
                            tag: el.tagName,
                            text: (el.innerText || el.value || el.getAttribute('aria-label') || '').trim(),
                            href: el.getAttribute('href') || '',
                            id: el.id || '',
                            cls: el.className || '',
                            visible: !!(el.offsetWidth || el.offsetHeight || el.getClientRects().length),
                            disabled: !!el.disabled
                          }))
                          .filter((item) => item.text || item.id || item.cls)
                          .slice(0, 12)
                        """
                    )
                except Exception:
                    candidates = []
                log(
                    f"{prefix} frame[{idx}] url={frame_url[:160]} text={frame_text[:160]} "
                    f"candidates={candidates}"
                )

            if self.debug_screenshots:
                try:
                    screenshot_path = f"debug_no_button_{int(asyncio.get_event_loop().time())}.png"
                    await self.page.screenshot(path=screenshot_path)
                    log(f"{prefix} 已保存截图: {screenshot_path}")
                except Exception:
                    pass

        # 尝试等待第一个按钮出现
        try:
            first_btn = self.page.locator('button:has-text("Agree"), [role="button"]:has-text("Agree"), button:has-text("Continue"), [role="button"]:has-text("Continue")').first
            await first_btn.wait_for(state="visible", timeout=10000)
            log("检测到首个操作按钮")
        except Exception as e:
            log(f"未能等待到首个操作按钮: {e}")
            await _log_page_diagnostics("按钮预检失败")

        while attempt < max_attempts:
            attempt += 1
            clicked_this_round = False

            # 实时检测 URL 变化，如果已跳转到 Google 域名则立即退出
            try:
                current_url = self.page.url
                if "accounts.google.com" in current_url or "myaccount.google.com" in current_url:
                    log(f"检测到验证完成，已跳转至: {current_url}")
                    return clicked_buttons
            except Exception as e:
                pass  # 页面可能正在加载，忽略错误

            # switch-device-age 伴随页在当前版本里经常停留在 QR tab。
            # 先显式切到 Link tab，再让后续通用按钮逻辑继续跑。
            try:
                current_text = await self.page.evaluate("document.body ? document.body.innerText : ''")
                if await _activate_companion_link_flow(current_url, current_text):
                    clicked_this_round = True
                    await asyncio.sleep(1.0)
            except Exception:
                pass

            if clicked_this_round:
                continue

            for config in button_configs:
                # 检查是否连续点击过多
                btn_name = config["name"]
                if consecutive_clicks.get(btn_name, 0) >= 5:
                    if attempt % 5 == 0: # 每 5 次尝试才重试一次被屏蔽的按钮
                        log(f"尝试重试被限制的按钮: {btn_name}")
                    else:
                        continue

                async for frame in _iter_frames():
                    for selector in config["selectors"]:
                        try:
                            btn = frame.locator(selector).first
                            if await btn.is_visible(timeout=1000):
                                is_disabled = await btn.is_disabled()
                                if not is_disabled:
                                    await btn.click()
                                    log(
                                        f"点击按钮: {config['name']} "
                                        f"(frame={frame.url[:120]}, 选择器: {selector})"
                                    )

                                    clicked_buttons.append(config['name'])
                                    clicked_this_round = True

                                    for k in consecutive_clicks:
                                        consecutive_clicks[k] = 0
                                    consecutive_clicks[btn_name] = consecutive_clicks.get(btn_name, 0) + 1

                                    if self.debug_screenshots:
                                        try:
                                            screenshot_path = f"debug_click_{len(clicked_buttons)}_{btn_name.replace(' ', '_')}.png"
                                            await self.page.screenshot(path=screenshot_path)
                                        except Exception:
                                            pass

                                    await asyncio.sleep(config["wait_after"])
                                    break
                        except Exception:
                            pass
                    if clicked_this_round:
                        break
                if clicked_this_round:
                    break

            if not clicked_this_round:
                await asyncio.sleep(0.8)  # 增加等待时间

                # 截图查看当前状态
                if self.debug_screenshots and attempt % 5 == 0:
                    try:
                        await self.page.screenshot(path=f"debug_waiting_{attempt}.png")
                        log(f"等待中... 已保存截图: debug_waiting_{attempt}.png")

                        # 打印页面文本帮助诊断
                        text = await self.page.evaluate("document.body.innerText")
                        # log(f"当前页面文本片段: {text[:200].replace(chr(10), ' ')}...")
                    except:
                        pass

                # 放宽早期退出条件
                if attempt in (5, 10, 15):
                    await _log_page_diagnostics(f"第 {attempt} 次轮询仍未点到按钮")

                if attempt >= 15 and not clicked_buttons:
                    log(f"{attempt} 次尝试后未找到任何按钮，退出")
                    break
                if attempt >= 20 and len(clicked_buttons) > 0:
                    log(f"已点击 {len(clicked_buttons)} 个按钮，无更多按钮")
                    break
            else:
                # 点击成功后重置尝试计数，继续寻找下一个按钮
                attempt = max(0, attempt - 2)

        return clicked_buttons

    async def _check_completion(self, log_callback=None) -> Dict[str, Any]:
        """检查验证是否完成"""
        def log(msg):
            if log_callback:
                try: log_callback(msg)
                except: pass
            else:
                print(f"[AgeVerify] {msg}")

        try:
            # 1. 检查 URL 变化 (最优先检查，无需等待页面完全加载)
            current_url = self.page.url
            if "myaccount.google.com" in current_url or "accounts.google.com" in current_url:
                log(f"检测到页面跳转回 Google: {current_url}")

                # 只要跳转回 Google 域名，且不在 privateid.com，通常意味着流程结束
                # 检查 URL 参数中是否包含结果标识，或者这是否是登录/后续页面

                if "result" in current_url or "success" in current_url:
                    return {
                        "completed": True,
                        "success": True,
                        "message": "验证流程已完成 (检测到结果页跳转)"
                    }
                elif "signin" in current_url:
                    # 如果跳转到登录页，检查 referrer 或参数中是否有 result
                    # PrivateID 完成后通常会带上 result 路径
                    if "result" in current_url or "%2Fresult" in current_url:
                         return {
                            "completed": True,
                            "success": True,
                            "message": "验证流程已完成 (检测到登录页跳转，含结果参数)"
                        }
                    else:
                        # 可能是无效链接直接跳回登录，但也可能是成功后 session 失效跳转
                        # 对于自动化流程，跳转回 Google 登录页通常视为验证环节已结束
                        log(f"跳转到登录页，视为验证环节结束")
                        return {
                            "completed": True,
                            "success": True, # 乐观假定成功，因为失败通常会停留在 PrivateID 页面或显示错误
                            "message": "验证流程已结束 (跳转回 Google 登录页)"
                        }
                elif "age-verification" in current_url:
                     return {
                        "completed": True,
                        "success": True,
                        "message": "验证流程已完成 (返回年龄验证页面)"
                    }
                else:
                    # 其他 Google 页面，也视为结束
                     return {
                        "completed": True,
                        "success": True,
                        "message": f"验证流程已结束 (跳转至 {current_url})"
                    }

            # 2. 检查 404/错误页面 (优先检查标题)
            try:
                page_title = await self.page.title()
                if "404" in page_title or "Not Found" in page_title:
                     return {
                        "completed": True,
                        "success": False,
                        "message": "链接无效 (404 Not Found)"
                    }
            except:
                pass

            # 3. 检查页面文本 (使用 locator 而不是 evaluate 整个 body，性能更好)
            try:
                # 检查特定元素是否存在，而不是获取全文
                # Google 404 页面通常有特定的结构
                if await self.page.locator("text=404").count() > 0 and await self.page.locator("text=Not Found").count() > 0:
                     return {
                        "completed": True,
                        "success": False,
                        "message": "链接无效 (404 Not Found)"
                    }

                # 获取页面可见文本用于其他检查
                page_text = await self.page.evaluate("document.body.innerText")
            except:
                page_text = ""

            # 检查成功标志
            for text in self.COMPLETION_TEXTS:
                if text.lower() in page_text.lower():
                    return {
                        "completed": True,
                        "success": True,
                        "message": "年龄验证成功完成"
                    }

            # 检查失败标志
            for text in self.FAILURE_TEXTS:
                if text.lower() in page_text.lower():
                    return {
                        "completed": True,
                        "success": False,
                        "message": "年龄验证失败"
                    }

            # 检查是否还在 PrivateID 页面
            if "privateid.com" not in current_url and "google.com" not in current_url:
                 # 如果跑到了其他地方
                 pass

            return {
                "completed": False,
                "success": False,
                "message": "验证进行中"
            }
        except Exception as e:
            # 忽略一些因页面跳转导致的元素访问错误
            if "Target closed" in str(e):
                return {
                    "completed": False,
                    "success": False,
                    "message": "页面已关闭"
                }
            return {
                "completed": False,
                "success": False,
                "message": f"检查状态出错: {str(e)}"
            }

    async def _wait_for_completion(self, log_callback=None) -> Dict[str, Any]:
        """等待验证完成"""
        start_time = asyncio.get_event_loop().time()

        while True:
            elapsed = asyncio.get_event_loop().time() - start_time
            if elapsed > self.timeout:
                return {
                    "completed": False,
                    "success": False,
                    "message": f"验证超时 ({self.timeout}秒)"
                }

            result = await self._check_completion(log_callback)
            if result["completed"]:
                return result

            await asyncio.sleep(1)

    async def verify(
        self,
        verification_url: str,
        video_file: str = None,
        wait_for_completion: bool = True,
        log_callback=None
    ) -> Dict[str, Any]:
        """
        执行年龄验证
        ...
        """
        def log(msg):
            print(f"[AgeVerify] {msg}")
            if log_callback:
                try:
                    log_callback(msg)
                except:
                    pass

        log("开始年龄验证")
        log(f"URL: {verification_url}")
        log(f"设备: {self.device_config['name']}")
        log(f"摄像头模式: 视频注入 (强制)")

        try:
            # 准备视频文件 (如果需要转码)
            actual_video_file = self._prepare_video_file(video_file)
            if actual_video_file != video_file:
                log(f"视频已转码为临时文件: {actual_video_file}")

            # 检查视频文件有效性
            if not actual_video_file or not os.path.exists(actual_video_file):
                log("警告: 未找到视频文件，将使用 Chrome 内置默认测试视频 (绿色画面)")
            else:
                log(f"使用视频文件: {actual_video_file}")

            # 设置浏览器
            await self._setup_browser(actual_video_file)

            # 导航到验证页面
            log("正在访问验证页面...")
            await self.page.goto(verification_url, wait_until="domcontentloaded", timeout=30000)
            await asyncio.sleep(2)

            # 自动点击按钮
            clicked_buttons = await self._auto_click_buttons(log_callback=log)
            log(f"点击了 {len(clicked_buttons)} 个按钮: {', '.join(clicked_buttons)}")

            if wait_for_completion:
                # 等待验证完成
                log(f"等待验证完成 (最长 {self.timeout} 秒)...")
                result = await self._wait_for_completion(log_callback=log)

                if result['success']:
                    log(f"验证完成: {result['message']}")
                else:
                    log(f"验证结束: {result['message']}")

                return {
                    "success": result["success"],
                    "message": result["message"],
                    "clicked_buttons": clicked_buttons,
                    "verification_url": verification_url
                }
            else:
                return {
                    "success": True,
                    "message": "验证流程已启动，请手动完成",
                    "clicked_buttons": clicked_buttons,
                    "verification_url": verification_url
                }

        except Exception as e:
            log(f"验证出错: {e}")
            return {
                "success": False,
                "message": f"验证出错: {str(e)}",
                "clicked_buttons": [],
                "verification_url": verification_url
            }

    async def close(self):
        """关闭浏览器和 Playwright"""
        if self.context:
            await self.context.close()
        if self.browser:
            await self.browser.close()
        if self.playwright:
            await self.playwright.stop()
        print("[AgeVerify] 浏览器已关闭")

        # 清理临时文件
        if self._temp_files:
            print(f"[AgeVerify] 清理 {len(self._temp_files)} 个临时文件...")
            for path in self._temp_files:
                try:
                    if os.path.exists(path):
                        os.remove(path)
                except Exception as e:
                    print(f"[AgeVerify] 清理临时文件失败 {path}: {e}")
            self._temp_files = []


def run_age_verification(
    verification_url: str,
    use_obs: bool = False,
    video_file: str = None,
    device: str = "pixel_7_pro",
    headless: bool = True,
    timeout: int = 60,
    wait_for_completion: bool = True
) -> Dict[str, Any]:
    """
    同步接口 - 执行年龄验证

    Args:
        verification_url: PrivateID 验证链接
        use_obs: 是否使用 OBS 虚拟摄像头
        video_file: Y4M 视频文件路径（非 OBS 模式）
        device: 设备配置名称
        headless: 是否无头模式
        timeout: 验证超时时间（秒）
        wait_for_completion: 是否等待验证完成

    Returns:
        dict: 验证结果
    """
    async def _run():
        service = AgeVerificationService(
            use_obs=use_obs,
            device=device,
            headless=headless,
            timeout=timeout
        )
        try:
            result = await service.verify(
                verification_url=verification_url,
                video_file=video_file,
                wait_for_completion=wait_for_completion
            )
            return result
        finally:
            await service.close()

    return asyncio.run(_run())


